-- DREISSIG_IN_ZEHN_SEK -> BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET feinmotorik = '$1$BESTANDEN$1$$2$$2$' WHERE feinmotorik = '$1$DREISSIG_IN_ZEHN_SEK$1$$2$$2$';
-- FUENFUNDZWANZIG_IN_ZEHN_SEK -> NICHT_BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET feinmotorik = '$1$NICHT_BESTANDEN$1$$2$$2$' WHERE feinmotorik = '$1$FUENFUNDZWANZIG_IN_ZEHN_SEK$1$$2$$2$';
-- NICHT_MOEGLICH -> NICHT_GEPRUEFT mit ANDERER GRUND UPDATE untersuchungschulrelevantebeeintraechtigung SET feinmotorik = '$1$NICHT_GEPRUEFT$1$$2$ANDERER_GRUND$2$' WHERE feinmotorik = '$1$NICHT_MOEGLICH$1$$2$$2$';
-- MEHR_ALS_ZEHN_SEKUNDEN -> BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET gleichgewichteinbeinstand = '$1$BESTANDEN$1$$2$$2$' WHERE gleichgewichteinbeinstand = '$1$MEHR_ALS_ZEHN_SEKUNDEN$1$$2$$2$';
-- WENIGER_ALS_ZEHN_SEKUNDEN -> NICHT_BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET gleichgewichteinbeinstand = '$1$NICHT_BESTANDEN$1$$2$$2$' WHERE gleichgewichteinbeinstand = '$1$WENIGER_ALS_ZEHN_SEKUNDEN$1$$2$$2$';
-- MEHR_ALS_VIER_METER -> BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET grobmotorikeinbeinhuepfen = '$1$BESTANDEN$1$$2$$2$' WHERE grobmotorikeinbeinhuepfen = '$1$MEHR_ALS_VIER_METER$1$$2$$2$';
-- WENIGER_ALS_VIER_METER -> NICHT_BESTANDEN UPDATE untersuchungschulrelevantebeeintraechtigung SET grobmotorikeinbeinhuepfen = '$1$NICHT_BESTANDEN$1$$2$$2$' WHERE grobmotorikeinbeinhuepfen = '$1$WENIGER_ALS_VIER_METER$1$$2$$2$';
